CREATE TABLE `sach_tacgia` (
  `Masach` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Matacgia` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Vaitrotacgia` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'Tác giả chính',
  PRIMARY KEY (`Masach`,`Matacgia`),
  KEY `fk_st_tacgia` (`Matacgia`),
  CONSTRAINT `fk_st_sach` FOREIGN KEY (`Masach`) REFERENCES `sach` (`Masach`) ON DELETE CASCADE,
  CONSTRAINT `fk_st_tacgia` FOREIGN KEY (`Matacgia`) REFERENCES `tacgia` (`Matacgia`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
